tool.command:

  ln -f -s ${input_top_path} ${input_top_path}_`echo $$`.${input_top_path.ext};

  ln -f -s ${input_traj_path} ${input_traj_path}_`echo $$`.${input_traj_path.ext};

  ln -f -s ${input_ndx_path} ${input_ndx_path}_`echo $$`.${input_ndx_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

fatslim_membranes

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__selection__dq__:__dq__${properties.selection}__dq__,__dq__cutoff__dq__:${properties.cutoff},__dq__begin_frame__dq__:${properties.begin_frame},__dq__end_frame__dq__:${properties.end_frame},__dq__ignore_no_box__dq__:${properties.ignore_no_box},__dq__return_hydrogen__dq__:${properties.return_hydrogen},__dq__binary_path__dq__:__dq__${properties.binary_path}__dq____cc____cc__'
  #end if

  #if str($input_top_path) != 'None':
    --input_top_path ${input_top_path}_`echo $$`.${input_top_path.ext}
  #end if

  #if str($input_traj_path) != 'None':
    --input_traj_path ${input_traj_path}_`echo $$`.${input_traj_path.ext}
  #end if

  #if str($input_ndx_path) != 'None':
    --input_ndx_path ${input_ndx_path}_`echo $$`.${input_ndx_path.ext}
  #end if


  --output_ndx_path $outname_output_ndx_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_top_path}_`echo $$`.${input_top_path.ext};

  rm -f ${input_traj_path}_`echo $$`.${input_traj_path.ext};

  rm -f ${input_ndx_path}_`echo $$`.${input_ndx_path.ext};


  if test -f $outname_output_ndx_path; then mv $outname_output_ndx_path $output_ndx_path; fi;
